/**
 * Original Reveal vector scenes for the thirteen scratch themes.
 * All artwork is generated by Canvas: no licensed images, fonts or libraries.
 * Dimensions are proportional, allowing portrait scratch cards and concert passes.
 */
export function drawScratchThemeArtwork(ctx, w, h, theme, {photo=false, landscape=false}={}) {
  const artW=landscape?w*.78:w, min=Math.min(artW,h);
  const X=n=>n*artW, Y=n=>n*h, R=n=>Math.max(1,n*min);
  const C=theme.highlight, A=theme.accent, P=theme.paper, D=theme.bg;
  const line=(a,b,c,d,color=C,width=.005,alpha=1)=>{
    ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=color;ctx.lineWidth=R(width);
    ctx.beginPath();ctx.moveTo(X(a),Y(b));ctx.lineTo(X(c),Y(d));ctx.stroke();ctx.restore();
  };
  const poly=(points,color,alpha=1,stroke=null)=>{
    ctx.save();ctx.globalAlpha=alpha;ctx.fillStyle=color;
    ctx.beginPath();
    points.forEach(([x,y],i)=>i?ctx.lineTo(X(x),Y(y)):ctx.moveTo(X(x),Y(y)));
    ctx.lineTo(X(points[0][0]),Y(points[0][1]));ctx.fill();
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=R(.005);ctx.stroke();}
    ctx.restore();
  };
  const disc=(x,y,r,color,alpha=1,ring=false)=>{
    ctx.save();ctx.globalAlpha=alpha;ctx.beginPath();
    ctx.arc(X(x),Y(y),R(r),0,Math.PI*2);
    if(ring){ctx.strokeStyle=color;ctx.lineWidth=R(.006);ctx.stroke();}
    else {ctx.fillStyle=color;ctx.fill();}
    ctx.restore();
  };
  const rect=(x,y,ww,hh,color,alpha=1)=>{
    ctx.save();ctx.globalAlpha=alpha;ctx.fillStyle=color;ctx.fillRect(X(x),Y(y),X(ww),Y(hh));ctx.restore();
  };
  const twinkle=(x,y,r,color=C)=>{
    line(x-r,y,x+r,y,color,.004,.87);
    line(x,y-r*h/Math.max(artW,1),x,y+r*h/Math.max(artW,1),color,.004,.87);
    disc(x,y,r*.18,color,.93);
  };
  const heart=(x,y,s,color)=>{
    // Parametric heart silhouette: every segment is native Canvas vector art.
    const pts=[];
    for(let i=0;i<=48;i++){
      const t=2*Math.PI*i/48;
      const px=16*Math.pow(Math.sin(t),3)/36;
      const py=-(13*Math.cos(t)-5*Math.cos(2*t)-2*Math.cos(3*t)-Math.cos(4*t))/38;
      pts.push([x+s*px,y+s*py]);
    }
    poly(pts,color,.88);
  };
  const ribbon=(x,y,r)=>{
    for(let k=0;k<5;k++)line(x+k*.018,y+k*.013,x+k*.025,y+.032+k*.012,k%2?A:C,.004,.85);
    disc(x,y,r,A,.8);
  };
  const triangle=(x,y,size,color,alpha=1)=>poly([[x,y-size],[x-size*.8,y+size*.62],[x+size*.8,y+size*.62]],color,alpha);
  const star=(x,y,r,points=5,color=C)=>{
    const ps=[];
    for(let i=0;i<points*2;i++){
      const theta=(Math.PI*i/points)-Math.PI/2,rad=i%2?r*.41:r;
      ps.push([x+rad*Math.cos(theta),y+rad*Math.sin(theta)]);
    }
    poly(ps,color,.93);
  };
  const cloud=(x,y,s,color=P)=>{
    disc(x-.055*s,y,.048*s,color,.9);
    disc(x,y-.018*s,.069*s,color,.93);
    disc(x+.06*s,y,.049*s,color,.9);
    rect(x-.062*s,y,.13*s,.025*s,color,.94);
  };
  const drawTree=(x,y,s)=>{
    triangle(x,y-.036*s,.11*s,A,.95);
    triangle(x,y+.018*s,.145*s,C,.85);
    triangle(x,y+.073*s,.18*s,A,.95);
    rect(x-.012*s,y+.13*s,.024*s,.045*s,D);
  };
  const burst=(x,y,s)=>{
    for(let i=0;i<12;i++){
      const t=2*Math.PI*i/12;
      line(x+Math.cos(t)*s*.3,y+Math.sin(t)*s*.18,x+Math.cos(t)*s,y+Math.sin(t)*s*.65,i%3===0?P:(i%2?A:C),.006,.91);
    }
    disc(x,y,s*.10,P);
  };
  ctx.save();
  // The metallic finish and selected original artwork remain beneath
  // the semi-translucent illustrated theme scene.
  if (!photo) {
    const background=ctx.createLinearGradient(0,0,artW,h);
    background.addColorStop(0,theme.bg);
    background.addColorStop(.55,theme.bg2);
    background.addColorStop(1,theme.bg);
    ctx.globalAlpha=.85;ctx.fillStyle=background;ctx.fillRect(0,0,artW,h);
    ctx.globalAlpha=1;
    // Illuminated foil-etched edge arcs give each card a coherent identity.
    for(let i=0;i<3;i++){
      ctx.strokeStyle=i%2?A:C;ctx.globalAlpha=.13+i*.06;
      ctx.lineWidth=R(.007);
      ctx.beginPath();ctx.arc(X(.5),Y(.52),R(.25+i*.11),0,Math.PI*2);ctx.stroke();
    }
    ctx.globalAlpha=1;
  } else {
    // Custom photographs stay clearly visible. Only a small translucent frame
    // and themed corner stamps are added; never paint the scene over the photo.
    ctx.globalAlpha=.72;ctx.fillStyle=D;
    ctx.fillRect(0,0,artW,h*.04);
    ctx.fillRect(0,h*.945,artW,h*.055);
    ctx.globalAlpha=1;
    for(const [x,y] of [[.11,.13],[.89,.13],[.10,.89],[.90,.89]])
      star(x,y,.027,5,C);
    ctx.restore();
    return;
  }

  switch(theme.id) {
    case 'adventure': {
      disc(.77,.25,.085,P,.78);
      poly([[0,.41],[.17,.22],[.3,.37],[.49,.19],[.69,.44],[.85,.27],[1,.38],[1,.52],[0,.52]],A,.72);
      poly([[0,.46],[.21,.34],[.43,.48],[.63,.29],[.84,.46],[1,.35],[1,.54],[0,.54]],D,.96);
      for(const [x,y] of [[.14,.28],[.5,.24],[.84,.31]])poly([[x-.032,y+.04],[x,y-.015],[x+.036,y+.04]],P,.77);
      for(let i=0;i<8;i++)disc(.18+i*.075,.72+Math.sin(i*.85)*.055,.005,P,.77);
      disc(.72,.79,.106,C,.15);disc(.72,.79,.088,C,.9,true);
      for(let i=0;i<8;i++){
        const a=Math.PI*i/4;line(.72,.79,.72+Math.sin(a)*.078,.79+Math.cos(a)*.053,P,.003,.78);
      }
      star(.72,.79,.052,4,A);
      for(const x of [.09,.26,.43,.91])drawTree(x,.87,.51);
      break;
    }
    case 'travel': {
      disc(.7,.29,.135,P,.8,true);disc(.7,.29,.112,C,.5,true);
      for(let i=-2;i<=2;i++)line(.7+i*.036,.21,.7+i*.036,.38,C,.003,.5);
      line(.57,.29,.83,.29,P,.004,.75);
      line(.59,.245,.81,.245,C,.002,.6);line(.59,.335,.81,.335,C,.002,.6);
      poly([[.18,.265],[.32,.25],[.36,.29],[.32,.31],[.24,.304],[.21,.335],[.18,.332],[.2,.3],[.13,.291]],P,.93);
      for(let i=0;i<10;i++)disc(.3+i*.027,.37+Math.sin(i*.41)*.018,.003,C,.8);
      rect(.12,.7,.29,.19,A,.81);rect(.14,.72,.25,.15,D,.96);
      disc(.255,.775,.028,C,.65,true);line(.255,.747,.255,.801,C,.004,.8);
      line(.228,.775,.282,.775,C,.004,.8);
      for(let i=0;i<4;i++)line(.16,.825+i*.012,.34,.825+i*.012,P,.003,.65);
      poly([[.68,.8],[.87,.76],[.9,.8],[.78,.82],[.73,.89],[.68,.89]],C,.88);
      break;
    }
    case 'magical': {
      disc(.77,.26,.077,P,.96);disc(.79,.242,.072,D,.98);
      for(const [x,y,r] of [[.19,.25,.027],[.37,.3,.019],[.6,.36,.024],[.91,.38,.016],[.27,.78,.02]])star(x,y,r,5,C);
      for(let i=0;i<17;i++)disc(.11+(i*37%82)/100,.2+(i*17%18)/100,.0035,P,.7);
      rect(.31,.72,.37,.17,A,.82);rect(.34,.65,.08,.24,D);rect(.56,.63,.07,.26,D);
      triangle(.38,.65,.073,C);triangle(.595,.63,.068,C);
      rect(.46,.69,.082,.20,D);triangle(.50,.67,.075,C);
      rect(.48,.81,.04,.08,A);disc(.50,.81,.02,P,.8);
      burst(.12,.81,.058);break;
    }
    case 'sports': {
      // Stadium floodlights, a football and a pitch with visible markings.
      for(const x of [.17,.84]){
        line(x,.23,x,.42,P,.009,.83);
        rect(x-.045,.225,.09,.022,P,.9);
        for(let k=0;k<3;k++)disc(x-.022+k*.022,.236,.008,C);
      }
      disc(.51,.28,.093,P,.97);star(.51,.28,.045,5,D);
      for(let i=0;i<5;i++)line(.51,.28,.51+Math.cos(i*1.25)*.085,.28+Math.sin(i*1.25)*.057,D,.004,.74);
      rect(.11,.69,.78,.21,A,.75);
      ctx.save();ctx.strokeStyle=P;ctx.globalAlpha=.86;ctx.lineWidth=R(.004);
      ctx.strokeRect(X(.15),Y(.715),X(.7),Y(.16));ctx.strokeRect(X(.15),Y(.755),X(.15),Y(.07));
      ctx.strokeRect(X(.7),Y(.755),X(.15),Y(.07));ctx.restore();
      line(.5,.715,.5,.875,P,.004,.84);disc(.5,.795,.05,P,.8,true);
      break;
    }
    case 'music': {
      disc(.29,.30,.125,D);disc(.29,.30,.11,C,.75,true);
      disc(.29,.30,.083,C,.57,true);disc(.29,.30,.051,P,.75);disc(.29,.30,.017,A);
      for(let i=0;i<13;i++){
        const x=.54+i*.026,amp=.018+(i%5)*.012;
        line(x,.30-amp,x,.30+amp,i%2?A:C,.009,.9);
      }
      rect(.14,.70,.72,.19,P,.95);
      for(let i=1;i<10;i++)line(.14+i*.072,.70,.14+i*.072,.89,D,.004,.7);
      for(const i of [1,2,4,5,6,8])rect(.14+i*.072-.015,.70,.03,.11,D,.95);
      for(const [x,y] of [[.18,.39],[.78,.38]]){disc(x,y,.028,C);line(x+.027,y,x+.027,y-.105,C,.009);line(x+.027,y-.105,x+.075,y-.13,C,.009);}
      break;
    }
    case 'theatre': {
      // Original auditorium-like curtain geometry and spotlit stage.
      poly([[.05,.19],[.29,.19],[.27,.38],[.22,.41],[.19,.36],[.13,.41],[.08,.34]],A,.98);
      poly([[.71,.19],[.95,.19],[.92,.38],[.86,.41],[.81,.36],[.76,.41],[.73,.35]],A,.98);
      for(let i=0;i<4;i++){
        line(.07+i*.052,.20,.075+i*.05,.39,P,.005,.67);
        line(.74+i*.052,.20,.75+i*.05,.39,P,.005,.67);
      }
      poly([[.39,.19],[.54,.19],[.70,.49],[.18,.49]],P,.14);
      poly([[.14,.86],[.5,.69],[.86,.86],[.86,.92],[.14,.92]],A,.85);
      for(let i=0;i<10;i++)disc(.13+i*.081,.88,.007,C,.92);
      star(.5,.29,.055,8,P);break;
    }
    case 'festive': {
      drawTree(.5,.305,1.25);
      for(let i=0;i<7;i++)disc(.40+i*.033,.25+(i%3)*.038,.012,i%2?P:A);
      star(.5,.175,.04,5,P);
      for(let i=0;i<18;i++)disc(.09+((i*41)%85)/100,.205+((i*31)%70)/100,.004+(i%3)*.002,P,.89);
      rect(.18,.73,.19,.15,A,.88);rect(.205,.73,.035,.15,P,.8);
      rect(.16,.785,.23,.026,P,.86);
      rect(.64,.75,.19,.13,C,.91);rect(.716,.75,.03,.13,D,.8);
      rect(.64,.80,.19,.025,D,.82);
      star(.84,.27,.027,6,P);break;
    }
    case 'romance': {
      heart(.53,.29,.31,A);heart(.53,.285,.23,C);
      heart(.20,.35,.10,P);heart(.83,.39,.12,P);
      for(const [x,y] of [[.2,.72],[.78,.76]]) {
        line(x,y+.17,x+.05,y-.018,C,.012,.75);
        for(let i=0;i<7;i++)disc(x+Math.cos(i*2.4)*.04,y+Math.sin(i*2.4)*.025,.019,i%2?A:P,.9);
        disc(x,y,.021,C);
        poly([[x+.019,y+.08],[x+.08,y+.1],[x+.04,y+.124]],A,.95);
      }
      for(let i=0;i<5;i++)heart(.30+i*.1,.87+(i%2)*.023,.046,i%2?C:P);
      break;
    }
    case 'birthday': {
      for(const [x,y,color] of [[.25,.29,A],[.52,.24,P],[.79,.3,C]]){
        disc(x,y,.069,color,.94);line(x,y+.065,x+.035,y+.16,P,.003,.84);
        triangle(x,y+.073,.016,color);
      }
      rect(.29,.76,.42,.12,P);rect(.32,.70,.36,.07,A);rect(.29,.82,.42,.035,C);
      for(let i=0;i<5;i++){
        const x=.35+i*.075;rect(x-.008,.65,.016,.056,P);
        poly([[x,.63],[x-.012,.644],[x,.658],[x+.012,.644]],C,.9);
      }
      for(let i=0;i<16;i++)ribbon(.12+(i*23%75)/100,.19+(i*31%72)/100,.004);
      break;
    }
    case 'baby': {
      cloud(.23,.28,1.18);cloud(.76,.31,.86);
      star(.51,.26,.034,5,C);
      for(let i=0;i<6;i++)star(.16+i*.14,.41+(i%2)*.045,.012,5,P);
      // Cot with cradle bars and a gently curved mobile, pastel on blue.
      rect(.22,.77,.56,.12,P,.95);
      rect(.20,.735,.045,.2,A);rect(.755,.735,.045,.2,A);
      for(let i=0;i<7;i++)line(.28+i*.074,.77,.28+i*.074,.89,A,.005,.9);
      line(.5,.64,.5,.72,P,.006,.9);line(.38,.65,.62,.65,P,.005,.85);
      for(const x of [.40,.50,.60]){
        line(x,.65,x,.70,P,.004,.85);
        star(x,.73,.018,5,A);
      }
      break;
    }
    case 'celebration': {
      burst(.24,.28,.115);burst(.74,.33,.125);burst(.55,.22,.057);
      for(let i=0;i<25;i++){
        const x=.07+((i*29)%88)/100,y=.21+((i*17)%74)/100;
        if(i%3===0)star(x,y,.011,4,i%2?P:C);
        else rect(x,y,.012,.023,i%2?A:P,.83);
      }
      for(let i=0;i<8;i++){
        line(.12+i*.11,.69,.08+i*.11,.89,i%2?C:P,.007,.8);
      }
      rect(.31,.79,.38,.09,A,.68);
      star(.5,.83,.043,8,P);break;
    }
    case 'mystery': {
      // Secret-lock sigil, question marks and an old-fashioned key.
      disc(.5,.29,.135,A,.26);disc(.5,.29,.108,C,.85,true);
      for(let i=0;i<8;i++){
        const t=Math.PI*2*i/8;
        const x=.5+Math.sin(t)*.132,y=.29+Math.cos(t)*.085;
        star(x,y,.017,4,P);
      }
      disc(.5,.285,.038,P);
      poly([[.477,.316],[.523,.316],[.546,.391],[.454,.391]],P,.9);
      line(.30,.78,.77,.78,P,.015,.86);
      disc(.28,.78,.067,C,.93,true);disc(.28,.78,.03,C,.6,true);
      rect(.66,.78,.028,.07,C);rect(.72,.78,.026,.05,C);
      for(let i=0;i<5;i++)twinkle(.15+i*.17,.71+(i%2)*.17,.017);
      break;
    }
    default: {
      // Luxury / Elegant: faceted gemstone and fine marbled gold filigree.
      poly([[.5,.19],[.67,.265],[.62,.365],[.5,.425],[.38,.365],[.33,.265]],P,.94,C);
      poly([[.33,.265],[.67,.265],[.5,.425]],A,.71);
      poly([[.42,.265],[.5,.19],[.58,.265],[.5,.425]],C,.83);
      line(.33,.265,.67,.265,D,.005,.8);
      for(let i=0;i<12;i++){
        const y=.69+i*.015;
        line(.11,y,.23+i*.009,y+.016,C,.003,.3);
        line(.77-i*.005,y+.034,.88,y,A,.003,.4);
      }
      for(const [x,y] of [[.22,.82],[.78,.82],[.5,.87]]) {
        disc(x,y,.057,C,.2);disc(x,y,.039,P,.8,true);
        star(x,y,.021,6,C);
      }
      break;
    }
  }

  // Theme-coloured outer engravings: keep the selected metallic finish
  // beneath them, especially on the original concert ticket stub.
  ctx.strokeStyle=C;ctx.lineWidth=R(.005);ctx.globalAlpha=.8;
  ctx.strokeRect(X(.045),Y(.19),X(.91),Y(.73));
  ctx.globalAlpha=.96;
  for(const [x,y] of [[.075,.21],[.925,.21],[.075,.90],[.925,.90]])
    star(x,y,.016,4,P);
  ctx.restore();
}
